.container {
  display: flex;
  justify-content: flex-start;  /* по умолчанию: элементы в начале */
  justify-content: flex-end;    /* элементы в конце */
  justify-content: center;      /* по центру */
  justify-content: space-between; /* равномерно, без отступов по краям */
  justify-content: space-around;  /* равномерно, с отступами по краям */
  justify-content: space-evenly;  /* абсолютно равномерно */
}

.container {
  display: flex;
  height: 200px; /* задаём высоту контейнера */
  align-items: stretch;    /* по умолчанию: растягиваются на всю высоту */
  align-items: flex-start; /* к верхнему краю */
  align-items: flex-end;   /* к нижнему краю */
  align-items: center;     /* по центру */
}

.center-container {
  display: flex;
  justify-content: center; /* по центру горизонтально */
  align-items: center;      /* по центру вертикально */
  height: 300px;
}

.container {
  display: flex;
  align-items: flex-start; /* все элементы наверху */
}

.container .highlight {
  align-self: flex-end; /* только этот элемент внизу */
}

.container {
  display: flex;
  flex-wrap: wrap;
  height: 300px;
  align-content: center; /* строки по центру */
}

/* row: justify = горизонталь, align = вертикаль */
.row {
  display: flex;
  justify-content: center; /* горизонтально по центру */
  align-items: center;      /* вертикально по центру */
}

/* column: justify = вертикаль, align = горизонталь */
.column {
  display: flex;
  flex-direction: column;
  justify-content: center; /* вертикально по центру */
  align-items: center;      /* горизонтально по центру */
}

.container {
  display: flex;
  gap: 16px;              /* одинаковый gap и по горизонтали, и по вертикали */
  row-gap: 12px;           /* только между строками */
  column-gap: 24px;        /* только между колонками */
}

.item {
  flex: 1 1 200px;
  /* flex-grow: 1  */
  /* flex-shrink: 1 */
  /* flex-basis: 200px */
}

/* Частые комбинации: */
.item-a { flex: 1; }     /* flex: 1 1 0% — занимает равную долю */
.item-b { flex: 0 0 200px; } /* фиксированный размер 200px */
.item-c { flex: 0 1 auto; }  /* не растягивается, сжимается, от содержимого */

.menu {
  display: flex;
  justify-content: space-between; /* логотип слева, меню справа */
  align-items: center;
  padding: 16px 24px;
}

.nav-links {
  display: flex;
  gap: 24px;
}

.hero {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.hero-content {
  text-align: center;
}

.cards {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: stretch; /* все карточки одной высоты */
}

.card {
  flex: 1 1 250px; /* мин. 250px, растягивается */
  padding: 20px;
}

.layout {
  display: flex;
  gap: 20px;
  min-height: 100vh;
}

.sidebar {
  flex: 0 0 250px; /* фиксированная ширина 250px */
}

.main {
  flex: 1; /* занимает всё оставшееся место */
}
